#!/usr/bin/env bash
# bd tree for pi-fusion MVP campaign (orchestrator-driven, one-shot)
set -euo pipefail
cd /d/Documents/Repositories/pi-fusion

E="pi-fusion-2rb"

mk() { # title desc acceptance [type] [parent]
  local out id
  out=$(bd create "$1" -d "$2" --acceptance "$3" -t "${4:-task}" ${5:+--parent "$5"} 2>&1)
  id=$(printf '%s' "$out" | grep -oE 'pi-fusion-[a-z0-9]+' | head -1)
  printf '%s %s\n' "$id" "$1"
}

# ---------- S1 фундамент ----------
S1=$(mk "S1: фундамент — типы, контракт, отчёт" "Этап S1 спеки 001: types.ts, contract/schema+validate, report/schema+validate (FR-002, FR-006)." "Все задачи S1 закрыты, гейты зелёные" epic "$E")

T1=$(mk "contract-schema: types.ts + contract/schema.ts" "Поле: extensions/pi-fusion/types.ts, extensions/pi-fusion/contract/schema.ts, test/contract-schema.test.ts. TypeBox-формы: FusionTask {id,instructions,title?,deliverable?,files?,maxSteps?,timeoutMs?,etaSeconds?}, DelegateContract (inputs?, owners?, provides?, requires?, checks?), FusionContract {tasks 1..16, maxWorkers?, contract?}, WorkerReport, TaskResult, UsageTotals, ProgressSnapshot, ClampRow, FanoutResult (см. design §4 Core Interfaces). Схема задач строгая: additionalProperties:false (неизвестные поля отклоняются; etaSeconds — известное игнорируемое), id: string 1..200 без CR/LF, instructions: 1..32000, files: массив 0..32 непустых строк, maxWorkers >= 1. TDD: сначала тесты форм." "Схемы экспортированы; тесты покрывают границы (16/17 задач, id 200/201, CR/LF, instructions 32000/32001, files 32/33, неизвестное поле отклонено); npm test/typecheck/lint/build зелёные" task "$S1")

T2=$(mk "contract-validate: порт валидатора atomic-agent" "Поле: extensions/pi-fusion/contract/validate.ts, test/contract-validate.test.ts. Порт правил atomic-agent delegate-args.ts:306-520 + contract.ts + contract-inputs.ts (файлы: D:/Documents/Repositories/atomic-agent/src/tools/fusion/): дубликаты id; contract не объект; inputs <=32 после trim+дедупа (дубликаты схлопываются, НЕ отказ); owners — ссылки только на известные задачи, пустые пути отклоняются; provides <=64 (MAX_CONTRACT_PROVIDES), kind из 7 значений атомика (symbol|file|id|endpoint|env|flag|other), shape <=200 ОБРЕЗАЕТСЯ (не отказ); requires = {task известная, name непустая}; checks <=16 (MAX_CONTRACT_CHECKS) с непустым spec; рендер блока контракта >8000 знаков = ОТКАЗ вызова; warnings ВЫЧИСЛЯЕТ парсер (несбываемость контракта уходит в warnings, не отказ); title без явного значения = humaniseTaskId(id) (replace [_-]+ пробелом, схлопнуть пробелы, trim, пустой результат = id); etaSeconds принимается и игнорируется. Ошибки: isError-форма {reason, offender}." "Все ветки FR-002 в тестах; рендер >8000 → отказ; shape обрезан → warning; humanise-тесты совпадают с атомиком; гейты зелёные" task "$S1")

T3=$(mk "report-schema: WorkerReport + validate + violatedFields" "Поле: extensions/pi-fusion/report/schema.ts, extensions/pi-fusion/report/validate.ts, test/report.test.ts. TypeBox-схема отчёта с if/then: status enum (done|no_changes|failed|needs_orchestrator), summary string, filesChanged/evidence/residualRisks string[], replacedExistingFiles? string[], question? string — ОБЯЗАТЕЛЕН при needs_orchestrator (if/then в самой схеме — хост вернёт structured_output_failed). validate.ts: violatedFields(report) — список нарушенных полей; no_changes требует filesChanged: [] (иначе violation). TDD." "Тесты: валидный отчёт ок; needs_orchestrator без question → violation (schema if/then); no_changes с непустым filesChanged → violation; violatedFields называет поля; гейты зелёные" task "$S1")

# ---------- S2 шов ----------
S2=$(mk "S2: шов делегирования pi-subagents" "Этап S2: fake-pi тест-инфраструктура + seam/client (FR-008, FR-010, FR-009 preflight)." "Все задачи S2 закрыты, гейты зелёные" epic "$E")

T4=$(mk "fake-pi: тестовая шина delegation-событий" "Поле: test/fake-pi.ts. Фейковая реализация шва поверх EventEmitter: emit request/started/update/response/cancel с валидными payload по типам C:/Users/user/.pi/agent/npm/node_modules/pi-subagents/src/api/delegation.d.ts; response-гейты по requestId (тест управляет порядком и содержимым ответов: статус, usage, result.value, error); helper для кумулятивных :update-снимков; совместимо с fake timers vitest. Эталон поведения хоста: .../src/slash/delegation-adapters.js." "fake-pi используется в тестах T5+: подписка/ответ маршрутизируется по requestId; cancel-событие доходит; гейты зелёные" task "$S2")

T5=$(mk "seam-client: availability + client (11 статусов, usage, cancel, dispose)" "Поле: extensions/pi-fusion/seam/availability.ts, extensions/pi-fusion/seam/client.ts, test/seam-client.test.ts. availability(pi): есть ли шина событий. client: один FanoutSeamClient на fan-out; run({nodeId, task, model, timeoutMs, hardToolBudget, onProgress}) -> SeamOutcome; подписка на :response, маршрутизация по попытко-специфичному requestId (fusion-<task.id>-a<attempt>-<seq>-<ts>), nodeId <task.id>#a<attempt>, ownerRunId fusion-<seq>-<ts>; локальный дедлайн timeoutMs+15s grace -> cancel({requestId, ownerRunId, nodeId}) и исход timeout; МАППИНГ 11 статусов (design §5 таблица, правила из delegation-adapters.js): cancelled, failed->hostError(окно/перегрузка/прочее по маркерам Q-002), timed_out, structured_output_failed->schemaFailed, tool_budget_exhausted, acceptance_failed, interrupted, completed->report|hostError(no-structured-output БЕЗ ретрая), unavailable_context, invalid_request, duplicate_node; usage прикладывается к ЛЮБОМУ терминальному исходу (кроме unavailableContext), :update-снимки НЕ суммируются, turnsObserved = последний снимок с usage ПОСЛЕДНЕЙ попытки; dispose(): отписки + resolve pending как {kind:cancelled}; ответы после dispose игнорируются; late response после таймаута игнорируется." "Тест-таблица 11 статусов (строка на литерал); grace -> :cancel с телом {requestId, ownerRunId, nodeId}; dispose резолвит pending; ignore-after-dispose; window-маркеры (quota/rate limit exceeded/limit reached/plan|billing limit) инкрементируют класс окна, перегрузка (overloaded/server busy/too many concurrent/try again later/529) — нет; usage с toolCalls=0 = нет данных; гейты зелёные" task "$S2")

# ---------- S3 пул ----------
S3=$(mk "S3: пул fan-out" "Этап S3: briefs + pool/fanout (FR-001, FR-003, FR-004, FR-011)." "Все задачи S3 закрыты, гейты зелёные" epic "$E")

T6=$(mk "briefs: рендер брифа задачи" "Поле: extensions/pi-fusion/briefs.ts, test/briefs.test.ts (или в pool.test). Формат design §4 Brief: контракт целиком JSON-блоком + разделитель; ## {title} (нормализованный ВАЛИДАЦИЕЙ title, сырой id не попадает); instructions; Deliverable: строка если есть; Scope files: через запятую если есть. В шов уходит только бриф. Чистые функции." "Тесты: все секции/их отсутствие; контракт в брифе целиком; humanised title; гейты зелёные" task "$S3")

T7=$(mk "pool-fanout: клампы, FIFO, ротация, окно rate-limit, дренаж" "Поле: extensions/pi-fusion/pool/fanout.ts, test/pool.test.ts, test/window.test.ts. runFanout(deps) по design §4: цепочка клампов maxParallel -> perModel(capacity=2*|workerModels|) -> tasks, ClampRow {field, requested, applied, reason} (первая строка requested = W_req = maxWorkers ?? cfg.workers; отдельной maxWorkers-строки НЕТ); width=0 из-за пустой ротации -> pre-flight: ВСЕ задачи немедленно failed(no-available-model), ClampRow noModels, 0 эмитов :request, attempts=0; FIFO по индексам; dispatch при running<width И есть модель с runningByModel<2; ротация round-robin с пропуском без ёмкости; ОКНО rate-limit: счётчик per-model, window-класс (от seam hostError windowClass=true) инкрементирует, любой другой исход модели СБРАСЫВАЕТ, >=5 подряд -> модель удалена из activeModels (НОВЫЕ запуски и очередь — на другие; БЕГУЩИЕ дети не отменяются — ни одного :cancel от пула; завершившиеся принимаются, упавшие терминальны с исходной причиной); activeModels пусто -> оставшаяся незапущенная очередь дренится failed(no-available-model); НИКАКИХ перезапусков задач; timeout -> failed(timeout) модель не трогается; результат в порядке индексов." "Тесты design §11: каждый фактор клампа и порядок строк; FIFO; per-model <=2 при 1/2/3 моделях; окно 5 подряд -> исключение + 0 :cancel + дети дорабатывают; дренаж; пустая ротация с fake-таймерами (очередь не оживает, вызов завершён); timeout на единственной модели не дренит; гейты зелёные" task "$S3")

# ---------- S4 сборка тула ----------
S4=$(mk "S4: сборка тула fusion_delegate" "Этап S4: report/retry, result, degradation, index.ts wiring + E2E (FR-005..FR-009)." "Все задачи S4 закрыты, гейты зелёные" epic "$E")

T8=$(mk "report-retry: 1 коррективный ретрай отчёта" "Поле: extensions/pi-fusion/report/retry.ts, test/report-retry.test.ts. Триггер — только SeamOutcome schemaFailed; коррективный request ТОЙ ЖЕ модели: 'Твой предыдущий отчёт нарушал схему: {fields}. Верни ТОЛЬКО JSON-отчёт о завершённой работе по схеме. Реализацию не повторять.' (fields из violatedFields); слот модели удержан; таймаут ретрая min(120s, task timeoutMs); повторный провал -> failed + schemaMissing:true; attempts=2; ретрай НОВЫЙ запуск (попытко-специфичный nodeId #a2 — не ловит duplicate_node); usage и turns суммируются по обоим запускам; ретрай НЕ инкрементирует счётчик окна." "Тесты: schemaFailed -> ретрай той же модели; успех -> report; второй schemaFailed -> failed+schemaMissing, attempts=2; usage суммирован; duplicate_node НЕ возникает (fake-мост с освобождением nodeId после терминала); гейты зелёные" task "$S4")

T9=$(mk "result + degradation: агрегат и честный отказ" "Поле: extensions/pi-fusion/result.ts, extensions/pi-fusion/degradation.ts, test/degradation.test.ts (result-тесты в fanout-e2e). result.ts: строки по исходным индексам; статусы TaskResult (done|no_changes|failed|needs_orchestrator|cancelled); error-коды (timeout|max_steps|schema-missing|seam-unavailable|no-available-model|host:<code>); timeout-подсказка 'возможно, taskTimeoutMs мал'; usage totals: сумма ТОЛЬКО терминальных по всем попыткам, absent = unknown; usagePartial=true если хоть одна задача без терминального usage (toolCalls/durationMs=0 от шва НЕ участвуют); turns = сумма терминальных turns, turnsObserved fallback; текстовая таблица id | status | summary | files + clamp-строки + usage-строка; needs_orchestrator поверх отчёта, отчёт учитывается только при completed. degradation.ts: preflight available()===false -> отказ 'fusion недоступен — делай работу сам' без воркеров (seamUnavailable); midrun unavailableContext -> задача failed(seam-unavailable), вызов продолжается, частичный результат; исключение модели при unavailableContext НЕ запускается." "Тесты: порядок индексов при перемешанном завершении; usagePartial; no_changes сквозной; done с пустым filesChanged НЕ превращается в no_changes; preflight-отказ 0 воркеров; midrun частичный результат; гейты зелёные" task "$S4")

T10=$(mk "tool-wiring: index.ts fusion_delegate + config-bridge + E2E" "Поле: extensions/pi-fusion/index.ts (ЗАМЕНИТЬ заглушку), extensions/pi-fusion/config-bridge.ts, test/fanout-e2e.test.ts. registerTool('fusion_delegate', exposure 'direct') + НЕМЕДЛЕННАЯ дизактивация setActiveTools(getActiveTools() без fusion_delegate) при enabled=false (активация — T12); outputSchema=FanoutResult, structuredContent + текст-таблица + details; ВЕРХНЕУРОВНЕВЫЙ result.usage = FanoutResult.usage (nested model calls); execute: validate -> availability -> runFanout; Esc ctx.signal -> cancel() in-flight + dispose() (pending -> cancelled, частичный результат); finally dispose. config-bridge.ts: read-only кэш {workers, maxParallel, taskTimeoutMs, workerModels, maxSteps} из config (T11, до него — дефолты: workers 3, maxParallel 3, taskTimeoutMs 600000, maxSteps 60, workerModels [] — пустая ротация честно дренится). E2E fake-pi ДВА сценария design §10.9: (а) 5 задач / width requested 3 -> фактическая 2 (cfg.maxParallel>=3; ЯВНЫЙ assert ClampRow {field:'perModel', requested:3, applied:2}) / 1 модель / timeout задачи -> failed(timeout)+подсказка, вызов продолжается; (б) 5 задач / width 3 / 2 модели: 5 подряд window-429 от A -> A исключена из НОВЫХ запусков, очередь на B, дети A дорабатывают (завершившиеся приняты), ЯВНЫЙ assert 0 :cancel от пула; + микс исходов done/no_changes/failed/needs_orchestrator/schema-failed->ретрай ok/Esc." "E2E (а) и (б) зелёные со всеми явными asserts §10.9; тул регистрируется, при enabled=false не в getActiveTools; Esc даёт частичный результат с cancelled; гейты зелёные" task "$S4")

# ---------- S5 MVP-обвязка ----------
S5=$(mk "S5: MVP-обвязка — конфиг, команда, гайданс, агент, лимит лида" "Этап S5 (PLAN F01-F03, F08, F19): config, /fusion, guidance, fusion-worker.md, restrictions." "Все задачи S5 закрыты, гейты зелёные" epic "$E")

T11=$(mk "config: fusion.json load/persist + валидация" "Поле: extensions/pi-fusion/config.ts, test/config.test.ts. Конфиг ~/.pi/agent/fusion.json: enabled (false), workers (3), maxParallel (3), taskTimeoutMs (600000), maxSteps (60), workerModels: string[] ([]), requireApproval (true), blockedTools (воркеру: ['fusion_delegate','subagent','codemode']), leadBlockedTools (['write','edit','bash']). Load: отсутствует -> дефолты; битый JSON -> дефолты + warn; валидация типов/границ (workers>=1, maxParallel 1..8, taskTimeoutMs 30000..3600000 и т.п.). Persist АТОМАРНО (tmp+rename). Путь резолвится от pi agent dir (PI_CODING_AGENT_DIR / ~/.pi/agent)." "Тесты: дефолты, битый JSON -> дефолты+warn, круговой цикл load->persist->load, атомарность (нет частичного файла), границы; гейты зелёные" task "$S5")

T12=$(mk "command: /fusion on|off|status|workers|model|timeout|help" "Поле: extensions/pi-fusion/commands.ts (или в index.ts), test/command.test.ts. registerCommand('fusion') + getArgumentCompletions (подкоманды on/off/status/workers/model/timeout/help/config); on/off: persist enabled + setActiveTools (включить/убрать fusion_delegate) + секция гайданса (T13) появляется/исчезает; workers/model/timeout меняют поля конфига с валидацией; status печатает состояние (enabled, модели, ширина, таймаут, наличие агента fusion-worker); help — текст. Состояние переживает рестарт (конфиг — истина). Референс UX: pi-autoresearch extensions/pi-autoresearch/commands.ts." "Тесты: каждая подкоманда меняет конфиг/активные тула; autocomplete выдаёт список; off снимает гайданс; гейты зелёные" task "$S5")

T13=$(mk "guidance: секция ### fusion через before_agent_start" "Поле: extensions/pi-fusion/guidance.ts, test/guidance.test.ts. Порт стратегии atomic-agent (D:/Documents/Repositories/atomic-agent/src/prompt/fusion-guidance.ts, fusion-machine-facts.ts): при enabled — append секции '### fusion' в systemPromptOptions.event.systemPromptOptions (ИДЕМПОТЕНТНО — фикс. заголовок, нет дублей), НИКОГДА не forceSystemPrompt; при off секция не добавляется/снимается. Содержание: лид планирует/делегирует/проверяет, рутина — воркерам; короткие самодостаточные брифы; проверка результатов: evidence из отчётов и/или делегирование проверки свежему воркеру (своего bash у лида нет — F19); needs_orchestrator = новый fan-out с путями в files; клампы честные. Machine facts: модели ротации, текущая ширина, таймаут." "Тесты: секция появляется при on, исчезает при off, повторный before_agent_start не дублирует; forceSystemPrompt не вызывается; гейты зелёные" task "$S5")

T14=$(mk "worker-agent: fusion-worker.md + установщик" "Поле: extensions/pi-fusion/agents/fusion-worker.md, extensions/pi-fusion/worker-install.ts, test/worker-install.test.ts. Агент: name fusion-worker, defaultContext fresh, inheritSkills false; allowlist тулов РОВНО read, grep, find, ls, bash, edit, write (НЕТ fusion/subagent/codemode); политика: одна задача, самодостаточный бриф, НЕ коммитить, НЕ трогать bd, запустить проверки (тесты/сборку) и приложить вывод в evidence, отчёт СТРОГО по схеме (status/summary/filesChanged/evidence/residualRisks/replacedExistingFiles?/question при needs_orchestrator); вне скоупа файлов не писать. Установщик: idempotent copy файла в <agentDir>/agents/fusion-worker.md (перезапись при обновлении — версия в заголовке файла), вызывается из /fusion config/on при отсутствии." "Тест: установщик создаёт файл, повторный запуск идемпотентен, в md нет запрещённых тулов в allowlist; агент резолвится форматом pi-агентов (референс: C:/Users/user/.pi/agent/agents/*.md и доки pi); гейты зелёные" task "$S5")

T15=$(mk "restrictions: лиду write/edit/bash заблокированы + barren-счётчик" "Поле: extensions/pi-fusion/restrictions.ts, test/restrictions.test.ts. Хендлер tool_call в ГЛАВНОЙ сессии: при enabled блокировать write, edit и bash ЦЕЛИКОМ (список leadBlockedTools); текст отказа по состоянию (порт atomic-agent fusion-orchestrator-mode.ts): до первого fan-out — 'планируй и делегируй — отправь fusion_delegate'; после fan-out с результатами — 'отправь переделку: needs_orchestrator = новый fan-out, пути — в files, не захватывай работу сам'; BARREN: 2 ПОДРЯД fan-out'а где все воркеры 0 шагов (turns/turnsObserved из результата) — 'воркер-нога не работает — скажи оператору'; мутации не разблокируются никогда в рамках turn'а (сброс счётчиков/фазы на turn_start); при off — пропуск (гейт не регистрируется/не срабатывает); read-only тула не трогаются; другие extension-тула не блокируются." "Тесты: блок в режиме, пропуск при off, оба текста отказа, переключение на barren-текст после 2 пустых fan-out'ов, неблокирующие тула проходят; гейты зелёные" task "$S5")

# ---------- S6 финал ----------
S6=$(mk "S6: живой прогон pi -p и финал" "Этап S6: smoke-обвязка, live-прогон на тестовом репо, README, финальные гейты." "Эпик кампании закрываем: все листья закрыты, live-прогон MVP подтверждён" epic "$E")

T16=$(mk "live-smoke: тест-репо + pi -p короткие задания + README" "Поле: scripts/smoke/, smoke-repo/ (генерируется скриптом), README.md. Обвязка: (1) unit-live smoke за env PI_FUSION_LIVE_SMOKE=1 (вне npm test): реальный шовный вызов fusion_delegate с 2 микрозадачами (structured result — живой прецедент TD-002) + проверка экспозиции (enabled=false -> тула нет в getActiveTools); (2) headless-прогон: генерируется тестовый git-репо (2-3 файла), pi -p с расширением и fusion on, короткое задание 'посчитай X в файлах и запиши Y — через fusion_delegate на >=2 задач'; критерии: лид отвечает, в результате >=2 задач со статусами, лид НЕ пользовался write/edit/bash ( restrictions), usage суммирован; (3) деградация: fusion off/без шва -> 'делай работу сам'. README: установка (pi install / -e), конфиг, контракт тула, ограничения, ссылки на спеку." "pi -p прогон на тестовом репо зелёный: >=2 воркера завершились, отчёты полны, лид сам не писал; деградация честная; README полный; npm test/typecheck/lint/build зелёные" task "$S6")

D() { bd dep add "$1" "$2" >/dev/null 2>&1 && printf 'dep %s <- %s ok\n' "$1" "$2" || printf 'dep %s <- %s FAIL\n' "$1" "$2"; }
D "$T2" "$T1"; D "$T3" "$T1"
D "$T4" "$T1"; D "$T5" "$T3"; D "$T5" "$T4"
D "$T6" "$T2"; D "$T7" "$T5"; D "$T7" "$T6"
D "$T8" "$T3"; D "$T8" "$T5"; D "$T9" "$T5"
D "$T10" "$T7"; D "$T10" "$T8"; D "$T10" "$T9"
D "$T11" "$T1"; D "$T12" "$T10"; D "$T12" "$T11"; D "$T13" "$T11"
D "$T15" "$T10"; D "$T15" "$T11"
D "$T16" "$T12"; D "$T16" "$T13"; D "$T16" "$T14"; D "$T16" "$T15"

echo "=== TREE ==="
cat <<EOF
E=$E
S1=$S1 T1=$T1 T2=$T2 T3=$T3
